changeSet.createProcedure:

CREATE OR REPLACE FUNCTION billing.ensure_account_for_user(p_user_id UUID)
RETURNS UUID AS
$$
DECLARE
    v_account_id UUID;
BEGIN
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'billing.ensure_account_for_user requires a non-null user id';
    END IF;

    LOOP
        SELECT id INTO v_account_id
        FROM billing.account
        WHERE user_id = p_user_id;

        IF v_account_id IS NOT NULL THEN
            RETURN v_account_id;
        END IF;

        BEGIN
            INSERT INTO billing.account (user_id, status)
            VALUES (p_user_id, 'active')
            RETURNING id INTO v_account_id;
            RETURN v_account_id;
        EXCEPTION WHEN unique_violation THEN
        END;
    END LOOP;
END;
$$
LANGUAGE plpgsql;

changeSet.sql:
UPDATE core.space s
SET account_id = billing.ensure_account_for_user(s.user_id)
WHERE s.account_id IS NULL;

changeSet.createProcedure:

CREATE OR REPLACE FUNCTION billing.space_account_sync_trigger_function()
RETURNS TRIGGER AS
$$
BEGIN
    NEW.account_id := billing.ensure_account_for_user(NEW.user_id);
    RETURN NEW;
END;
$$
LANGUAGE plpgsql;

changeSet.sql:

DROP TRIGGER IF EXISTS billing_space_account_sync_trigger ON core.space;
CREATE TRIGGER billing_space_account_sync_trigger
BEFORE INSERT OR UPDATE OF user_id ON core.space
FOR EACH ROW
EXECUTE FUNCTION billing.space_account_sync_trigger_function();

changeSet.createProcedure:

CREATE OR REPLACE FUNCTION billing.space_usage_seed_trigger_function()
RETURNS TRIGGER AS
$$
BEGIN
    INSERT INTO billing.space_usage (space_id, storage_bytes_used, storage_bytes_reserved, updated_at)
    VALUES (NEW.id, 0, 0, now())
    ON CONFLICT (space_id) DO NOTHING;
    RETURN NEW;
END;
$$
LANGUAGE plpgsql;

changeSet.sql:

DROP TRIGGER IF EXISTS billing_space_usage_seed_trigger ON core.space;
CREATE TRIGGER billing_space_usage_seed_trigger
AFTER INSERT ON core.space
FOR EACH ROW
EXECUTE FUNCTION billing.space_usage_seed_trigger_function();

GRANT USAGE ON SCHEMA billing TO ${app_user};
GRANT SELECT, INSERT, UPDATE, DELETE ON billing.account TO ${app_user};
GRANT SELECT, INSERT, UPDATE, DELETE ON billing.plan TO ${app_user};
GRANT SELECT, INSERT, UPDATE, DELETE ON billing.plan_limit TO ${app_user};
GRANT SELECT, INSERT, UPDATE, DELETE ON billing.account_subscription TO ${app_user};
GRANT SELECT, INSERT, UPDATE, DELETE ON billing.space_usage TO ${app_user};
GRANT SELECT, INSERT, UPDATE, DELETE ON billing.space_usage_event TO ${app_user};

changeSet.createProcedure:

CREATE OR REPLACE FUNCTION billing.account_default_subscription_trigger_function()
RETURNS TRIGGER AS
$$
DECLARE
    v_basic_plan_id UUID;
BEGIN
    SELECT id INTO v_basic_plan_id
    FROM billing.plan
    WHERE code = 'basic';

    IF v_basic_plan_id IS NULL THEN
        RAISE EXCEPTION 'billing.account_default_subscription_trigger_function requires the basic plan to exist';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM billing.account_subscription s
        WHERE s.account_id = NEW.id
          AND (s.effective_to IS NULL OR s.effective_to > now())
          AND lower(s.status) IN ('active', 'trialing', 'grace_period')
    ) THEN
        INSERT INTO billing.account_subscription (account_id, plan_id, status, effective_from, source)
        VALUES (NEW.id, v_basic_plan_id, 'active', now(), 'system_default_basic');
    END IF;

    RETURN NEW;
END;
$$
LANGUAGE plpgsql;

changeSet.sql:

DROP TRIGGER IF EXISTS billing_account_default_subscription_trigger ON billing.account;
CREATE TRIGGER billing_account_default_subscription_trigger
AFTER INSERT ON billing.account
FOR EACH ROW
EXECUTE FUNCTION billing.account_default_subscription_trigger_function();
